insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('UA', 'default', 'План рахунків бухгалтерського обліку (наказ Мінфіну № 291)', '{"en":"Chart of accounts (order of the Ministry of Finance No. 291)"}'::jsonb, true, 'companies', array['UA-NPSBO1-BS', 'UA-NPSBO1-IS']::text[], null, 'Наказ Міністерства фінансів України від 30.11.1999 № 291, який затверджує План рахунків та Інструкцію про його застосування, обов''язковий для підприємств, організацій та інших юридичних осіб (крім банків і бюджетних установ) незалежно від форм власності, організаційно-правових форм і видів діяльності. Цей пакет транскрибує рахунки та найуживаніші субрахунки першого порядку; Інструкція № 291 (вступна частина) прямо дозволяє підприємствам вводити субрахунки другого і третього порядків із збереженням кодів (номерів) субрахунків цього Плану рахунків — на цій підставі пакет додає чотиризначні субрахунки 6411-6414 (розмежування нарахованого/вхідного ПДВ і розрахунків з бюджетом) та 6851 (транзитний рахунок сум, що потребують з''ясування); див. README.md.', 'instr-291')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

