values
  ('UA', 'UA-P-14', 'ПДВ 14 % — окремі види сільськогосподарської продукції (купівля)', '{"en":"VAT 14% — selected agricultural products (purchase)"}'::jsonb, null, 'percent', 14, 'purchase', 'domestic', date '2022-03-01', null, 'Податковий кодекс України, підпункт «г» пункту 193.1 статті 193 та пункт 198.3 статті 198 — податковий кредит на придбання сільськогосподарської продукції за товарними позиціями 1001, 1003, 1005, 1201, 1205, 1206 00 УКТЗЕД, оподаткованої постачальником за ставкою 14 %.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-P-20', 'ПДВ 20 % — придбання на митній території (купівля)', '{"en":"VAT 20% — domestic purchase"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2011-01-01', null, 'Податковий кодекс України, підпункт «а» пункту 193.1 статті 193 та пункт 198.3 статті 198 — податковий кредит звітного періоду складається із сум податку, нарахованих (сплачених) платником за основною ставкою в разі придбання товарів/послуг.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-P-7', 'ПДВ 7 % — ліки, вироби медичного призначення, готельні та культурні послуги (купівля)', '{"en":"VAT 7% — medicines, hotel and cultural services (purchase)"}'::jsonb, null, 'percent', 7, 'purchase', 'domestic', date '2021-01-01', null, 'Податковий кодекс України, підпункт «в» пункту 193.1 статті 193 та пункт 198.3 статті 198 — податковий кредит на придбання лікарських засобів, медичних виробів або послуг з тимчасового розміщування (готельних послуг), оподаткованих постачальником за ставкою 7 %.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-S-14', 'ПДВ 14 % — окремі види сільськогосподарської продукції (продаж)', '{"en":"VAT 14% — selected agricultural products (sale)"}'::jsonb, null, 'percent', 14, 'sale', 'domestic', date '2022-03-01', null, 'Податковий кодекс України, підпункт «г» пункту 193.1 статті 193 — ставка 14 відсотків бази оподаткування застосовується до операцій з постачання на митній території України та ввезення на митну територію України сільськогосподарської продукції за товарними позиціями 1001, 1003, 1005, 1201, 1205, 1206 00 згідно з УКТЗЕД. Перелік кодів і період їх застосування уточнювалися наступними змінами до цього підпункту (окремі маркетингові роки); поточну редакцію переліку перевірити з бухгалтером перед застосуванням до конкретної операції.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-S-20', 'ПДВ 20 % — постачання на митній території (продаж)', '{"en":"VAT 20% — domestic supply (sale)"}'::jsonb, null, 'percent', 20, 'sale', 'domestic', date '2011-01-01', null, 'Податковий кодекс України, підпункт «а» пункту 193.1 статті 193 — основна ставка податку становить 20 відсотків бази оподаткування.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-S-7', 'ПДВ 7 % — ліки, вироби медичного призначення, готельні та культурні послуги (продаж)', '{"en":"VAT 7% — medicines, hotel and cultural services (sale)"}'::jsonb, null, 'percent', 7, 'sale', 'domestic', date '2021-01-01', null, 'Податковий кодекс України, підпункт «в» пункту 193.1 статті 193 — ставка 7 відсотків застосовується до постачання зареєстрованих в Україні лікарських засобів і медичних виробів (з 1 квітня 2014 року), а з 1 січня 2021 року — до послуг з тимчасового розміщування, що надаються готелями і подібними засобами тимчасового розміщування (пункт 74 підрозділу 2 розділу XX ПКУ, надалі — на постійній основі), та до послуг у сфері культури і мистецтва за переліком, затвердженим Кабінетом Міністрів України. Цей пакет транскрибує ставку одним кодом для трьох категорій; дата, з якої кожна конкретна категорія (ліки, готелі, культура) підпадає під 7 %, різна — перевірити з бухгалтером для операції поза готельним сектором.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-S-EXEMPT-EDU', 'Звільнено від ПДВ — освітні послуги (продаж)', '{"en":"VAT exempt — education services (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2011-01-01', null, 'Податковий кодекс України, підпункт 197.1.2 пункту 197.1 статті 197 — звільняються від оподаткування операції з постачання послуг з вищої, середньої, професійно-технічної та дошкільної освіти закладами освіти, які мають ліцензію на надання таких послуг.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null),
  ('UA', 'UA-S-EXPORT', 'ПДВ 0 % — експорт товарів (продаж)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2011-01-01', null, 'Податковий кодекс України, підпункт 195.1.1 пункту 195.1 статті 195 — нульова ставка застосовується до операцій з вивезення товарів за межі митної території України у митному режимі експорту.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'pku', null, null, null, null)
