insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format,
   rounding_unit, rounding_reference, rounding_source_key)
values
  ('UA', 'UA-PDV', 'Податкова декларація з податку на додану вартість', array['month']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Наказ Міністерства фінансів України від 28.01.2016 № 21, у редакції наказу від 09.08.2024 № 400 — форма податкової декларації з податку на додану вартість та Порядок її заповнення і подання. Податковий кодекс України, пункт 202.1 статті 202 — базовий звітний (податковий) період для цієї декларації дорівнює календарному місяцю для кожного платника (квартальний період, який раніше пункт 202.2 надавав платникам єдиного податку групи 3, скасовано Законом України від 28.12.2014 № 71-VIII з 1 січня 2016 року). Цей пакет транскрибує лише рядки, які постачання його власних податків досягають: основну ставку та ставки 7 % і 14 % (рядок 1), нульову ставку на експорт (рядок 2), операції, звільнені від оподаткування та/або що не є об''єктом оподаткування (рядок 5), придбання з правом на податковий кредит за тими самими ставками (рядок 10) та підсумкові рядки 9, 17, 18, 19. Рядки коригувань (7, 8, 14, 15, 16), придбання без права на кредит або без ПДВ (10.4), імпорт (рядки 11-12), послуги від нерезидента (рядки 6, 13) та розподіл/перенесення від''ємного значення (рядки 20-21) не відтворені — див. README.md та docs/international.md, розділ «From Ukraine».', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Податковий кодекс України, пункт 203.1 статті 203 — податкова декларація подається за базовий звітний (податковий) період, що дорівнює календарному місяцю, протягом 20 календарних днів, що настають за останнім календарним днем звітного (податкового) місяця. Сума податкового зобов''язання, зазначена в декларації, підлягає сплаті протягом ще 10 календарних днів після цього строку (пункт 203.2) — тобто фактично до 30-го числа; це поле моделює лише строк подання декларації, а не строк сплати, який socle не розрізняє (див. README.md).', 'pku', null, 1, 'Порядок заповнення і подання податкової звітності з податку на додану вартість, затверджений наказом Мінфіну від 28.01.2016 № 21, розділ III, пункт 4 — усі показники податкової звітності з ПДВ проставляються у гривнях без копійок з відповідним округленням за загальновстановленими правилами.', 'pdv-deklaracija-nakaz-21')
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  rounding_unit       = excluded.rounding_unit,
  rounding_reference  = excluded.rounding_reference,
  rounding_source_key = excluded.rounding_source_key,
  file_format         = excluded.file_format;

