insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('UA-NPSBO1-BS', 'UA', 'default', 'Баланс (Звіт про фінансовий стан) — форма № 1', 'balance_sheet', 'НП(С)БО 1', date '2013-01-01', null, 'Національне положення (стандарт) бухгалтерського обліку 1 «Загальні вимоги до фінансової звітності», затверджене наказом Мінфіну від 07.02.2013 № 73, додаток 1, форма № 1. Цей пакет транскрибує підсумкові рядки форми (нетто-балансова вартість за кожною групою активів), без окремих граф «первісна вартість» / «знос», без рядків, специфічних для страхових компаній і недержавних пенсійних фондів (1060, 1065, 1650, 1670, 1800) та без рядка 1200/1700 (необоротні активи, утримувані для продажу) — жодний рахунок цього пакета їх не потребує. Див. README.md.', 'npsbo-1'),
  ('UA-NPSBO1-IS', 'UA', 'default', 'Звіт про фінансові результати (Звіт про сукупний доход) — форма № 2', 'income_statement', 'НП(С)БО 1', date '2013-01-01', null, 'Національне положення (стандарт) бухгалтерського обліку 1, додаток 1, форма № 2, розділ I «Фінансові результати». Форма розрізняє для кожного проміжного підсумку окремий рядок «прибуток» і окремий рядок «збиток» (наприклад 2090/2095, 2190/2195, 2290/2295, 2350/2355), з яких лише один заповнюється в кожному звітному періоді; цей пакет спрощує кожну таку пару в один рядок зі знаком (додатне значення — прибуток, від''ємне — збиток), а також не відтворює розділи II «Сукупний доход», III «Елементи операційних витрат» і IV «Розрахунок показників прибутковості акцій», які жодний рахунок цього пакета не потребує. Див. README.md.', 'npsbo-1')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

