update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Закон України «Про бухгалтерський облік та фінансову звітність в Україні» від 16.07.1999 № 996-XIV, стаття 9 — первинні документи, зокрема податкові накладні та видаткові накладні, складаються під час здійснення господарської операції; форма нумерації податкової накладної визначена Порядком заповнення податкової накладної (наказ Мінфіну від 31.12.2015 № 1307) і не збігається обов''язково з номером комерційного документа. Формат тут — приклад послідовної нумерації, а не єдино нав''язана форма.',
  numbering_source_key          = 'pku',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Податковий кодекс України, пункт 187.1 статті 187 — датою виникнення податкових зобов''язань з постачання товарів/послуг вважається дата, яка припадає на податковий (звітний) період, протягом якого відбувається будь-яка з подій, що сталася раніше: або дата зарахування коштів від покупця/замовника, або дата відвантаження товарів (оформлення документа на постачання послуг) — «правило першої події». Це не є принципом, від якого дата рахунку є винятком (як у Бельгії чи Люксембурзі): жодна з двох дат не переважає іншу за умовчанням, тому системного слова цього поля («дата рахунку», «дата поставки») не існує рівно для цього правила; `invoice_if_issued` тут наближення — оплата чи відвантаження, що сталися раніше, а не виставлення рахунку, фіксують подію. Прогалину socle щодо «першої з двох дат» без прив''язки до рахунку задокументовано в README.md та в docs/international.md, розділ «From Ukraine».',
  tax_point_source_key          = 'pku',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Закон України «Про бухгалтерський облік та фінансову звітність в Україні», стаття 9, частина 5 — виправлення помилок у первинних документах здійснюється способом, який передбачає складання нового документа (зокрема, розрахунку коригування) і не допускає стирання чи виправлення без слідів; Податковий кодекс України, пункт 192.1 статті 192 — коригування податкових зобов''язань і податкового кредиту здійснюється шляхом складання розрахунку коригування до податкової накладної, зареєстрованого в ЄРПН.',
  posted_edit_policy_source_key = 'pku',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Кожна платна поставка товарів/послуг платника ПДВ супроводжується складенням податкової накладної, яка підлягає обов''язковій реєстрації в Єдиному реєстрі податкових накладних (ЄРПН) — Податковий кодекс України, статті 201.1 та 201.10, без порогу суми з часу скасування такого порогу (Закон України від 21.12.2016 № 1797-VIII, набрав чинності 01.01.2017). Реєстрація підпорядкована граничним строкам, різним залежно від половини місяця складення (стаття 201.10), і системі моніторингу критеріїв оцінки ступеня ризиків (СМКОР, постанова КМУ від 11.12.2019 № 1165), яка може зупинити реєстрацію окремої накладної до розгляду. `profile` тут залишено порожнім, а не заповнено умовною національною назвою: податкова накладна — це структурований документ, який податкова накладна складається у форматі, визначеному ДПС (наказ Мінфіну від 31.12.2015 № 1307, з подальшими змінами), і подається до ЄРПН через спеціалізоване програмне забезпечення (M.E.Doc, Вчасно тощо) або кабінет платника — вона не є жодним із профілів, побудованих на семантичній моделі EN 16931 (Peppol BIS, Factur-X, XRechnung, PINT), і не є обміном між рівними сторонами: реєстрація в ЄРПН — це умова, від якої залежить право покупця на податковий кредит (стаття 201.10), а не факт випуску самого документа продавцем, який лишається за продавцем. `party_scheme` і `vat_scheme` лишаються порожніми з тієї ж причини: в України немає учасницької схеми ISO 6523, зареєстрованої в мережі Peppol. Прогалину socle щодо реєстрації в державному реєстрі, її строків і блокування (СМКОР) задокументовано в README.md та в docs/international.md, розділ «From Ukraine».',
  einvoice_source_key           = 'yerpn-postanova-1165',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'UA';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('UA', 'reverse_charge', 'reverse_charge', 'Податок на додану вартість нараховується та сплачується отримувачем послуг самостійно відповідно до пункту 208.2 статті 208 Податкового кодексу України.', '{"en":"VAT is charged and paid by the recipient of the service, on their own account, under article 208.2 of the Tax Code of Ukraine."}'::jsonb, 10, date '1970-01-01', null, 'Податковий кодекс України, пункт 208.2 статті 208 — отримувач послуг, наданих нерезидентом, місце постачання яких розташоване на митній території України, є особою, відповідальною за нарахування та сплату податку до бюджету.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
